// Generated by `xark client` from `schema.json`: a typed client for the `sha256` circuit.
//
//   #[circuit]
//   fn sha256(msg: Private<[u8; 3]>, digest: Public<Hash>)
//
// `xark build` records the circuit's parameter types in target/xark/sha256/schema.json
// and `xark client` turns them into the types below. Don't edit this file: change
// the circuit, then rebuild and rerun `xark client`. Values go in their natural
// forms (dates, strings, variant names, bytes); xark-wasm encodes them against the
// schema (in `sha256.schema.ts`, written with this file), exactly as `xark prove
// --inputs` does.

import { CheckFailed, Circuit, Field, InputError, fromHex, toHex, type Json, type Proof, type Prover, type Verifier } from "@blueshift-gg/xark-wasm/client";
import schema from "./sha256.schema";
export { CheckFailed, Field, InputError, fromHex, toHex };

/** Every input of `sha256`. */
export interface Sha256Inputs {
  /** `[u8; 3]`: exactly 3 bytes. */
  msg: Uint8Array;
  /** `Hash`: its 32 bytes. */
  digest: Uint8Array;
}

/** The public inputs: what a verifier supplies, and what a proof reveals. */
export interface Sha256PublicInputs {
  /** `Hash`: its 32 bytes. */
  digest: Uint8Array;
}

/** The public inputs, decoded from a proof. */
export interface Sha256PublicValues {
  digest: Uint8Array;
}

/**
 * `sha256`: make a prover or verifier from a URL serving a copy of
 * `target/xark/sha256/` (relative to the page in a browser) or from the bytes:
 *
 * ```ts
 * const prover = await Sha256.prover("/circuits/sha256/");
 * const proof = prover.prove(inputs);
 * send(proof.toBytes()); // the proof; an exported Solana verifier reads it as is
 * const verifier = await Sha256.verifier(vkBytes);
 * verifier.verify(bytes, publicInputs); // true: it proves the public inputs you require
 * ```
 */
export const Sha256 = new Circuit<Sha256Inputs, Sha256PublicInputs, Sha256PublicValues, {}>({
  name: "sha256",
  schema,
  decodePublic,
  client: false,
  digest: "b64403b37d24e75de2ee0f3f41a32bfa",
});

export type Sha256Prover = Prover<Sha256Inputs, Sha256PublicInputs, Sha256PublicValues, {}>;
export type Sha256Verifier = Verifier<Sha256PublicInputs, Sha256PublicValues, {}>;
export type Sha256Proof = Proof<Sha256PublicValues>;

function decodePublic(v: Json<Sha256PublicValues>): Sha256PublicValues {
  return {
    digest: fromHex(v.digest),
  };
}
